∀ (n : ℕ),
  OAI.BorsukNine.SimplicialChains.crossTower n 0 =
    OAI.BorsukNine.SimplicialChains.simplex (OAI.BorsukNine.SimplicialChains.cross n) {(0, false)}

∀ {V : Type u_1} (K : PreAbstractSimplicialComplex V) (d : ℕ),
