∀ (n : ℕ),
  OAI.BorsukNine.SimplicialChains.dropLast n =
    { toFun := fun x => WithLp.toLp 2 fun i => x.ofLp i.castSucc, map_add' := ⋯, map_smul' := ⋯ }

