∀ {f : ℂ → ℝ} {a : ℝ} {field : ℂ → ℂ} {lipschitzConstant : NNReal} {smooth : ContDiff ℝ (↑⊤) field}
  {compact : HasCompactSupport field} {lipschitz : LipschitzWith lipschitzConstant field}
  {tangent : ∀ (z : ℂ), (fderiv ℝ f z) (field z) = 0} {trajectory : { z // f z = a } → ℝ → ℂ}
  {initial : ∀ (z : { z // f z = a }), trajectory z 0 = ↑z}
  {equation : ∀ (z : { z // f z = a }) (t : ℝ), HasDerivAt (trajectory z) (field (trajectory z t)) t}
  {scalar : ∀ (z : { z // f z = a }) (t : ℝ), f (trajectory z t) = a}
  {trajectory_smooth : ∀ (z : { z // f z = a }), ContDiff ℝ (↑⊤) (trajectory z)}
  {regular : ∀ (z : { z // f z = a }) (t : ℝ), deriv (trajectory z) t ≠ 0} {field_1 : ℂ → ℂ}
  {lipschitzConstant_1 : NNReal} {smooth_1 : ContDiff ℝ (↑⊤) field_1} {compact_1 : HasCompactSupport field_1}
  {lipschitz_1 : LipschitzWith lipschitzConstant_1 field_1} {tangent_1 : ∀ (z : ℂ), (fderiv ℝ f z) (field_1 z) = 0}
  {trajectory_1 : { z // f z = a } → ℝ → ℂ} {initial_1 : ∀ (z : { z // f z = a }), trajectory_1 z 0 = ↑z}
  {equation_1 : ∀ (z : { z // f z = a }) (t : ℝ), HasDerivAt (trajectory_1 z) (field_1 (trajectory_1 z t)) t}
  {scalar_1 : ∀ (z : { z // f z = a }) (t : ℝ), f (trajectory_1 z t) = a}
  {trajectory_smooth_1 : ∀ (z : { z // f z = a }), ContDiff ℝ (↑⊤) (trajectory_1 z)}
  {regular_1 : ∀ (z : { z // f z = a }) (t : ℝ), deriv (trajectory_1 z) t ≠ 0},
  { field := field, lipschitzConstant := lipschitzConstant, smooth := smooth, compact := compact,
        lipschitz := lipschitz, tangent := tangent, trajectory := trajectory, initial := initial, equation := equation,
        scalar := scalar, trajectory_smooth := trajectory_smooth, regular := regular } =
      { field := field_1, lipschitzConstant := lipschitzConstant_1, smooth := smooth_1, compact := compact_1,
        lipschitz := lipschitz_1, tangent := tangent_1, trajectory := trajectory_1, initial := initial_1,
        equation := equation_1, scalar := scalar_1, trajectory_smooth := trajectory_smooth_1, regular := regular_1 } →
    field = field_1 ∧ lipschitzConstant = lipschitzConstant_1 ∧ trajectory = trajectory_1

