  {π : OAI.CircleDomainRigidity.Sphere → OAI.CircleDomainRigidity.Sphere} {B : Set OAI.CircleDomainRigidity.Sphere}
  {p : I → OAI.CircleDomainRigidity.Sphere} {O : I → Set OAI.CircleDomainRigidity.Sphere} {H : I → ℂ ≃ₜ ℂ}
  {curve : I → Circle → ℂ} {fiber_subset : ∀ (i : I), {z | π ↑z = p i} ⊆ OAI.CircleDomainRigidity.jordanInterior (H i)}
  {closure_subset : ∀ (i : I), closure (OAI.CircleDomainRigidity.jordanInterior (H i)) ⊆ (fun z => π ↑z) ⁻¹' O i}
  {disjoint_closures :
    Pairwise (Function.onFun Disjoint fun i => closure (OAI.CircleDomainRigidity.jordanInterior (H i)))}
  {curve_smooth :
    ∀ (i : I), ContMDiff (modelWithCornersSelf ℝ (EuclideanSpace ℝ (Fin 1))) (modelWithCornersSelf ℝ ℂ) (↑⊤) (curve i)}
  {curve_embedding : ∀ (i : I), Topology.IsEmbedding (curve i)}
  {frontier_eq : ∀ (i : I), frontier (OAI.CircleDomainRigidity.jordanInterior (H i)) = Set.range (curve i)}
  {frontier_good : ∀ (i : I), ∀ z ∈ frontier (OAI.CircleDomainRigidity.jordanInterior (H i)), ↑z ∈ G ∧ π ↑z ∉ B}
  {H_1 : I → ℂ ≃ₜ ℂ} {curve_1 : I → Circle → ℂ}
  {fiber_subset_1 : ∀ (i : I), {z | π ↑z = p i} ⊆ OAI.CircleDomainRigidity.jordanInterior (H_1 i)}
  {closure_subset_1 : ∀ (i : I), closure (OAI.CircleDomainRigidity.jordanInterior (H_1 i)) ⊆ (fun z => π ↑z) ⁻¹' O i}
  {disjoint_closures_1 :
    Pairwise (Function.onFun Disjoint fun i => closure (OAI.CircleDomainRigidity.jordanInterior (H_1 i)))}
  {curve_smooth_1 :
    ∀ (i : I),
      ContMDiff (modelWithCornersSelf ℝ (EuclideanSpace ℝ (Fin 1))) (modelWithCornersSelf ℝ ℂ) (↑⊤) (curve_1 i)}
  {curve_embedding_1 : ∀ (i : I), Topology.IsEmbedding (curve_1 i)}
  {frontier_eq_1 : ∀ (i : I), frontier (OAI.CircleDomainRigidity.jordanInterior (H_1 i)) = Set.range (curve_1 i)}
  {frontier_good_1 : ∀ (i : I), ∀ z ∈ frontier (OAI.CircleDomainRigidity.jordanInterior (H_1 i)), ↑z ∈ G ∧ π ↑z ∉ B},
  { H := H, curve := curve, fiber_subset := fiber_subset, closure_subset := closure_subset,
        disjoint_closures := disjoint_closures, curve_smooth := curve_smooth, curve_embedding := curve_embedding,
        frontier_eq := frontier_eq, frontier_good := frontier_good } =
      { H := H_1, curve := curve_1, fiber_subset := fiber_subset_1, closure_subset := closure_subset_1,
        disjoint_closures := disjoint_closures_1, curve_smooth := curve_smooth_1, curve_embedding := curve_embedding_1,
        frontier_eq := frontier_eq_1, frontier_good := frontier_good_1 } →
    H = H_1 ∧ curve = curve_1

