∀ {E : Type u_1} {inst : NormedAddCommGroup E} {inst_1 : InnerProductSpace ℝ E}
  {G : E → OAI.WeakMTWGlobalSupport.CoordinateGeometry.MetricTensor E} {S : Set E} {x₀ : E} {time : ℝ}
  {time_pos : 0 < time} {domain : Set (ℝ × E × E)} {domain_open : IsOpen domain} {flow : ℝ × E × E → E × E}
  {flow_smooth : ContDiffOn ℝ (↑⊤) flow domain} {initial : ∀ (q : E × E), (0, q) ∈ domain → flow (0, q) = q}
  {ode :
    ∀ q ∈ domain,
      (flow q).1 ∈ S ∧
        HasDerivAt (fun t => flow (t, q.2)) (OAI.WeakMTWGlobalSupport.CoordinateGeometry.geodesicSpray G (flow q)) q.1}
  {normal : OpenPartialHomeomorph (E × E) (E × E)} {normal_apply : ∀ (q : E × E), ↑normal q = (q.1, (flow (time, q)).1)}
  {center_mem : (x₀, 0) ∈ normal.source} {source_stays : ∀ q ∈ normal.source, ∀ t ∈ Set.Icc 0 time, (t, q) ∈ domain}
  {inverse_smooth : ContDiffOn ℝ (↑⊤) (↑normal.symm) normal.target}
  {normal_derivative_invertible : ∀ q ∈ normal.source, ∃ L, fderiv ℝ (↑normal) q = ↑L} {time_1 : ℝ}
  {time_pos_1 : 0 < time_1} {domain_1 : Set (ℝ × E × E)} {domain_open_1 : IsOpen domain_1} {flow_1 : ℝ × E × E → E × E}
  {flow_smooth_1 : ContDiffOn ℝ (↑⊤) flow_1 domain_1} {initial_1 : ∀ (q : E × E), (0, q) ∈ domain_1 → flow_1 (0, q) = q}
  {ode_1 :
    ∀ q ∈ domain_1,
      (flow_1 q).1 ∈ S ∧
        HasDerivAt (fun t => flow_1 (t, q.2)) (OAI.WeakMTWGlobalSupport.CoordinateGeometry.geodesicSpray G (flow_1 q))
          q.1}
  {normal_1 : OpenPartialHomeomorph (E × E) (E × E)}
  {normal_apply_1 : ∀ (q : E × E), ↑normal_1 q = (q.1, (flow_1 (time_1, q)).1)}
  {center_mem_1 : (x₀, 0) ∈ normal_1.source}
  {source_stays_1 : ∀ q ∈ normal_1.source, ∀ t ∈ Set.Icc 0 time_1, (t, q) ∈ domain_1}
  {inverse_smooth_1 : ContDiffOn ℝ (↑⊤) (↑normal_1.symm) normal_1.target}
  {normal_derivative_invertible_1 : ∀ q ∈ normal_1.source, ∃ L, fderiv ℝ (↑normal_1) q = ↑L},
  { time := time, time_pos := time_pos, domain := domain, domain_open := domain_open, flow := flow,
        flow_smooth := flow_smooth, initial := initial, ode := ode, normal := normal, normal_apply := normal_apply,
        center_mem := center_mem, source_stays := source_stays, inverse_smooth := inverse_smooth,
        normal_derivative_invertible := normal_derivative_invertible } =
      { time := time_1, time_pos := time_pos_1, domain := domain_1, domain_open := domain_open_1, flow := flow_1,
        flow_smooth := flow_smooth_1, initial := initial_1, ode := ode_1, normal := normal_1,
        normal_apply := normal_apply_1, center_mem := center_mem_1, source_stays := source_stays_1,
        inverse_smooth := inverse_smooth_1, normal_derivative_invertible := normal_derivative_invertible_1 } →
    time = time_1 ∧ domain = domain_1 ∧ flow = flow_1 ∧ normal = normal_1

