∀ {t : ℝ} {γ : Type u_2} {S : Schoenflies.CellStructure γ} {d : S.SubdivData} {R : S.Realization} ⦃g x y : γ⦄,
  d.skeleton.IsLink g x y →
    d.realizeCell R t g = Graph.edgeArc (d.realizeDrawing R t) g \ {d.realizePos R t x, d.realizePos R t y}

∀ {γ : Type u_1} {S : Schoenflies.CellStructure γ} {d : S.SubdivData} {R : S.Realization}
  {outer dom : Set Schoenflies.Plane} {t : ℝ} (ht : t ∈ Set.Ioo 0 1),
  R.IsWeaklyAdmissible outer dom → (d.realize R t ht).IsWeaklyAdmissible outer dom

∀ {γ : Type u_2} {S : Schoenflies.CellStructure γ} (d : S.SubdivData) (R : S.Realization) (t : ℝ) (c : γ),
  d.realizeCell R t c =
    if c = d.newVertex then {R.drawing d.edge t}
    else
      if c = d.newEdge₁ then R.drawing d.edge '' Set.uIcc (d.leftParam R) t \ {R.pos d.left, R.drawing d.edge t}
      else
        if c = d.newEdge₂ then R.drawing d.edge '' Set.uIcc t (d.rightParam R) \ {R.drawing d.edge t, R.pos d.right}
        else R.cell c

