∀ {k τ ρ u f f' : ℝ},
  τ ≠ 0 →
    ρ ≠ 0 →
      have p := τ * u ^ 2 * f;
      have pu := 2 * τ * u * f - τ / ρ * f';
      p - u * pu / 2 = τ * u / (2 * ρ) * f' ∧ (k * p + (1 - k * u) * pu / 2) / τ = u * f - (1 - k * u) / (2 * ρ) * f'

∀ {k τ u α β αu βu : ℝ},
  τ ≠ 0 →
    (1 - k * u) * αu + τ * u * βu + k * α - τ * β = 0 →
      have p := (1 - k * u) * α + τ * u * β;
      have pu := -k * α + (1 - k * u) * αu + τ * β + τ * u * βu;
      α = p - u * pu / 2 ∧ β = (k * p + (1 - k * u) * pu / 2) / τ

∀ {k τ ks τs u α β αs βs αu βu : ℝ},
  τ ≠ 0 →
    (1 - k * u) * αs + τ * u * βs = 0 →
      (1 - k * u) * αu + τ * u * βu + k * α - τ * β = 0 →
        have p := (1 - k * u) * α + τ * u * β;
        have pu := -k * α + (1 - k * u) * αu + τ * β + τ * u * βu;
        have ps := -ks * u * α + (1 - k * u) * αs + τs * u * β + τ * u * βs;
        have lam := τs / τ;
        have D := ks - k * lam;
        ps - u / 2 * (lam + u * D) * pu = -u * D * p

